create table if not exists public.atlas_stream_runtime_projection_v1 (stream_id text primary key,source_id text not null,jurisdiction_id text not null,module_hint text not null,status text not null,governance_contract_id text,runnable boolean not null default false,adapter_name text,schedule_priority text,interval_hours integer,observation_count bigint not null default 0 check (observation_count >= 0),identity_bound_observation_count bigint not null default 0 check (identity_bound_observation_count >= 0),observation_classification_count integer not null default 0 check (observation_classification_count >= 0),first_observed_at timestamptz,latest_observed_at timestamptz,latest_ingested_at timestamptz,last_run_status text,last_run_outcome text,last_run_at timestamptz,last_error text,snapshot_hash text not null check (snapshot_hash ~ '^[0-9a-f]{64}$'),observed_at timestamptz not null,is_current boolean not null default true,updated_at timestamptz not null default now()); comment on table public.atlas_stream_runtime_projection_v1 is 'Read-only Lighthouse projection of Atlas canonical stream/runtime state. Not an ownership table.'; create index if not exists atlas_stream_runtime_projection_current_idx on public.atlas_stream_runtime_projection_v1 (is_current,status,runnable); revoke all on public.atlas_stream_runtime_projection_v1 from public,anon,authenticated; create or replace function public.register_atlas_stream_runtime_snapshot_v1(p_snapshot jsonb) returns jsonb language plpgsql security definer set search_path = pg_catalog, public, pg_temp as $$ declare v_stream jsonb; v_seen integer:=0; v_observed_at timestamptz; v_snapshot_hash text; v_stream_ids text[]:='{}'::text[]; begin if jsonb_typeof(p_snapshot)<>'object' or jsonb_typeof(p_snapshot->'streams')<>'array' then raise exception 'atlas_stream_snapshot_object_required'; end if; v_snapshot_hash:=p_snapshot->>'snapshot_hash'; if coalesce(v_snapshot_hash,'') !~ '^[0-9a-f]{64}$' then raise exception 'atlas_stream_snapshot_hash_invalid'; end if; begin v_observed_at:=(p_snapshot->>'observed_at')::timestamptz; exception when others then raise exception 'atlas_stream_snapshot_observed_at_invalid'; end; for v_stream in select value from jsonb_array_elements(p_snapshot->'streams') loop if coalesce(v_stream->>'stream_id','')='' or coalesce(v_stream->>'source_id','')='' or coalesce(v_stream->>'jurisdiction_id','')='' or coalesce(v_stream->>'module_hint','')='' or coalesce(v_stream->>'status','')='' then raise exception 'atlas_stream_snapshot_row_invalid'; end if; v_stream_ids:=array_append(v_stream_ids,v_stream->>'stream_id'); end loop; update public.atlas_stream_runtime_projection_v1 set is_current=false,updated_at=now() where is_current=true and not (stream_id=any(v_stream_ids)); for v_stream in select value from jsonb_array_elements(p_snapshot->'streams') loop insert into public.atlas_stream_runtime_projection_v1 (stream_id,source_id,jurisdiction_id,module_hint,status,governance_contract_id,runnable,adapter_name,schedule_priority,interval_hours,observation_count,identity_bound_observation_count,observation_classification_count,first_observed_at,latest_observed_at,latest_ingested_at,last_run_status,last_run_outcome,last_run_at,last_error,snapshot_hash,observed_at,is_current,updated_at) values (v_stream->>'stream_id',v_stream->>'source_id',v_stream->>'jurisdiction_id',v_stream->>'module_hint',v_stream->>'status',nullif(v_stream->>'governance_contract_id',''),coalesce((v_stream->>'runnable')::boolean,false),nullif(v_stream->>'adapter_name',''),nullif(v_stream->>'schedule_priority',''),nullif(v_stream->>'interval_hours','')::integer,greatest(coalesce((v_stream->>'observation_count')::bigint,0),0),greatest(coalesce((v_stream->>'identity_bound_observation_count')::bigint,0),0),greatest(coalesce((v_stream->>'observation_classification_count')::integer,0),0),nullif(v_stream->>'first_observed_at','')::timestamptz,nullif(v_stream->>'latest_observed_at','')::timestamptz,nullif(v_stream->>'latest_ingested_at','')::timestamptz,nullif(v_stream->>'last_run_status',''),nullif(v_stream->>'last_run_outcome',''),nullif(v_stream->>'last_run_at','')::timestamptz,nullif(v_stream->>'last_error',''),v_snapshot_hash,v_observed_at,true,now()) on conflict (stream_id) do update set source_id=excluded.source_id,jurisdiction_id=excluded.jurisdiction_id,module_hint=excluded.module_hint,status=excluded.status,governance_contract_id=excluded.governance_contract_id,runnable=excluded.runnable,adapter_name=excluded.adapter_name,schedule_priority=excluded.schedule_priority,interval_hours=excluded.interval_hours,observation_count=excluded.observation_count,identity_bound_observation_count=excluded.identity_bound_observation_count,observation_classification_count=excluded.observation_classification_count,first_observed_at=excluded.first_observed_at,latest_observed_at=excluded.latest_observed_at,latest_ingested_at=excluded.latest_ingested_at,last_run_status=excluded.last_run_status,last_run_outcome=excluded.last_run_outcome,last_run_at=excluded.last_run_at,last_error=excluded.last_error,snapshot_hash=excluded.snapshot_hash,observed_at=excluded.observed_at,is_current=true,updated_at=now(); v_seen:=v_seen+1; end loop; return jsonb_build_object('status','completed','streams_registered',v_seen,'snapshot_hash',v_snapshot_hash,'observed_at',v_observed_at,'registered_at',clock_timestamp()); end; $$; revoke all on function public.register_atlas_stream_runtime_snapshot_v1(jsonb) from public,anon,authenticated;
